// commandInterpreter.js
export class CommandInterpreter {
  constructor(content) {
    this.content = content;
  }

  interpret() {
    const lines = this.content.split('\n');
    for (let line of lines) {
      const trimmed = line.trim();
      if (trimmed.startsWith("imprimir(") && trimmed.endsWith(")")) {
        const match = trimmed.match(/imprimir\((".*?"|'.*?')\)/);
        if (match) {
          const text = match[1].slice(1, -1);
          console.log(text);
        } else {
          console.error("Error de sintaxis en imprimir()");
        }
      }
    }
  }
}
